// Get the first item’s 'output' field
const input = $json.output;

// Remove the markdown code block formatting (```json ... ```)
const cleaned = input
  .replace(/```json\n?/, '')
  .replace(/```/, '')
  .trim();

// Parse the cleaned string into a JSON object
const parsed = JSON.parse(cleaned);

// Return the parsed JSON so the next node can use it
return [{ json: { cleaned_folder_json: parsed } }];

// Input format:
// [
//   {
//     "cleaned_folder_json": [ ...large array... ]
//   }
// ]

const input = $json.cleaned_folder_json;

if (!Array.isArray(input)) {
  throw new Error("cleaned_folder_json must be an array");
}

// CONFIG: batch size
const BATCH_SIZE = 1;

// Split into batches
const batches = [];
for (let i = 0; i < input.length; i += BATCH_SIZE) {
  const chunk = input.slice(i, i + BATCH_SIZE);
  batches.push(chunk);
}

// Return as separate items
return batches.map(batch => ({
  json: {
    batch
  }
}));

