return [
  {
    "file_path": $input.first().json.batch[0].file_path,
    "content": ""
  }
]

// STEP 1 — Read raw output safely
let raw = $json.output;

if (!raw || typeof raw !== "string") {
  // throw new Error("No valid output string found from AI.");
  return {
    json: {
       file_path: $('Prepare CodeGen Input').first().json.batch[0].file_path,
       content: ""
    }
  }
}

if($input.first().json.output.startsWith("[")){
  return {
    json: {
       file_path: $('Prepare CodeGen Input').first().json.batch[0].file_path,
       content: ""
    }
  }
}

// STEP 2 — Remove all markdown code fences and language tags
raw = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/^json\s*/gi, '')
  .trim();

// STEP 3 — Remove problematic control characters
raw = raw
  .replace(/[\u0000-\u001F]+/g, ' ')   // remove non-printable chars
  .replace(/\r/g, '')
  .replace(/\t/g, ' ')
  .trim();

// STEP 4 — Extract ONLY the JSON array using regex
const match = raw.match(/\[\s*{[\s\S]*}\s*\]/);

if (!match) {
  // throw new Error("Could not locate JSON array inside output.");
  return {
    json: {
       file_path: $('Prepare CodeGen Input').first().json.batch[0].file_path,
       content: ""
    }
  }
}

let cleanJson = match[0];

// STEP 5 — Parse JSON safely
let parsed;
try {
  parsed = JSON.parse(cleanJson);
} catch (err) {
  // throw new Error("JSON parsing failed: " + err.message + "\nClean JSON:\n" + cleanJson);
  return {
    json: {
       file_path: $('Prepare CodeGen Input').first().json.batch[0].file_path,
       content: ""
    }
  }
}

// STEP 6 — Validate array
if (!Array.isArray(parsed)) {
  // throw new Error("The extracted JSON is not an array.");
  return {
    json: {
       file_path: $('Prepare CodeGen Input').first().json.batch[0].file_path,
       content: ""
    }
  }
}

// STEP 7 — Convert to n8n items
return parsed.map(f => ({
  json: {
    file_path: f.file_path,
    content: f.content ?? ""
  }
}));

