    "file_path": "src/components/ParallaxBackground.jsx",
    "content": "import React, { useRef, useEffect } from 'react';
import gsap from 'gsap';

const ParallaxBackground = () => {
  const backgroundRef = useRef(null);

  useEffect(() => {
    const element = backgroundRef.current;

    const handleScroll = () => {
      const scrollY = window.scrollY;
      // Adjust the multiplier to control the parallax speed
      // A smaller multiplier means slower scrolling, thus more parallax effect
      const parallaxSpeed = 0.3; 
      gsap.to(element, {
        y: scrollY * parallaxSpeed,
        ease: 'power1.out',
        duration: 0.1, // Keep duration low for responsiveness
      });
    };

    window.addEventListener('scroll', handleScroll);

    // Initial setup to apply position based on current scroll position if page isn't at top
    handleScroll();

    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  return (
    <div
      ref={backgroundRef}
      className="absolute inset-0 z-0 w-full h-full bg-cover bg-center"
      style={{
        backgroundImage: 'url("/images/hero-background.jpg")', // Replace with your background image path
        backgroundAttachment: 'fixed', // This helps with the fixed background feel, but JS adds the movement
        transform: 'translateZ(-1px) scale(1.5)', // Example styling for depth, adjust as needed
        willChange: 'transform',
      }}
    >
      {/* Optional: Add an overlay for color tint or effects */}
      <div className="absolute inset-0 bg-black opacity-50"></div>
    </div>
  );
};

export default ParallaxBackground;
