import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

import SkillProgressIndicator from './SkillProgressIndicator';
import useScrollAnimation from '../../hooks/useScrollAnimation';

gsap.registerPlugin(ScrollTrigger);

const TechnicalSkillsSection = () => {
  const skillsSectionRef = useRef(null);
  const frontendSkillsRef = useRef([]);
  const backendSkillsRef = useRef([]);
  const devOpsSkillsRef = useRef([]);

  // Data for skills - categories and their respective skills
  const skillsData = [
    {
      category: 'Frontend Development',
      skills: [
        { name: 'React', level: 90 },
        { name: 'JavaScript (ES6+)', level: 95 },
        { name: 'HTML5', level: 98 },
        { name: 'CSS3 (Tailwind CSS)', level: 92 },
        { name: 'TypeScript', level: 85 },
      ],
    },
    {
      category: 'Backend Development',
      skills: [
        { name: 'Node.js', level: 88 },
        { name: 'Express.js', level: 85 },
        { name: 'Python (Django/Flask)', level: 75 },
        { name: 'RESTful APIs', level: 90 },
        { name: 'GraphQL', level: 70 },
      ],
    },
    {
      category: 'DevOps & Tools',
      skills: [
        { name: 'Docker', level: 80 },
        { name: 'Kubernetes', level: 65 },
        { name: 'AWS', level: 75 },
        { name: 'CI/CD (GitHub Actions)', level: 85 },
        { name: 'Git', level: 95 },
      ],
    },
  ];

  // Custom hook for scroll-triggered animations
  useScrollAnimation({
    triggerRef: skillsSectionRef,
    animations: skillsData.flatMap((categoryData, catIndex) => [
      // Animate category titles
      {
        elementRef: useRef(null), // Placeholder, will be assigned dynamically
        animation: { y: 30, opacity: 1, duration: 0.8, ease: 'power2.out' },
        start: 'top 70%',
        // Assign to category refs later
      },
      // Animate individual skill indicators
      ...categoryData.skills.map((_, skillIndex) => ({
        elementRef: useRef(null), // Placeholder, will be assigned dynamically
        animation: { y: 50, opacity: 1, duration: 1, ease: 'power2.out', delay: 0.1 * skillIndex },
        start: 'top 75%',
        // Assign to skill refs later
      })),
    ]),
    // A callback to assign refs after the component mounts and before animations start
    onEnterViewport: (animate) => {
      const categoryTitleRefs = Array.from(skillsSectionRef.current.querySelectorAll('.category-title'));
      const skillIndicatorRefs = Array.from(skillsSectionRef.current.querySelectorAll('.skill-indicator'));

      let skillIndex = 0;
      skillsData.forEach((categoryData, catIndex) => {
        // Assign category title refs
        const titleRef = categoryTitleRefs[catIndex];
        if (titleRef) {
          animate({ elementRef: { current: titleRef }, animation: { y: 30, opacity: 1, duration: 0.8, ease: 'power2.out' }, start: 'top 70%' });
        }

        // Assign skill indicator refs
        categoryData.skills.forEach((_, skillIndexInCategory) => {
          const indicatorRef = skillIndicatorRefs[skillIndex];
          if (indicatorRef) {
            animate({
              elementRef: { current: indicatorRef },
              animation: { y: 50, opacity: 1, duration: 1, ease: 'power2.out', delay: 0.1 * skillIndexInCategory },
              start: 'top 75%',
            });
          }
          skillIndex++;
        });
      });
    },
  });

  // Inline styles for initial hidden state
  const initialStyle = {
    opacity: 0,
    y: 20,
  };

  return (
    <section ref={skillsSectionRef} className="py-16 px-4 text-gray-100">
      <div className="container mx-auto max-w-4xl">
        <h3 className="text-4xl font-bold text-center mb-12 text-transparent bg-clip-text bg-gradient-to-r from-teal-400 to-blue-500">
          Technical Skills
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
