            <div key={catIndex} className="bg-gray-800 bg-opacity-50 rounded-lg p-6 shadow-lg transition-shadow duration-300 hover:shadow-xl">
              <h4
                className="text-2xl font-semibold mb-6 text-center text-teal-400 category-title"
