    "file_path": "src/components/SkillProgressIndicator.jsx",
    "content": "import React, { useEffect, useRef } from 'react';
import gsap from 'gsap';

const SkillProgressIndicator = ({ name, level }) => {
  const progressBarRef = useRef(null);
  const progressOverlayRef = useRef(null);
  const skillNameRef = useRef(null);

  useEffect(() => {
    const tl = gsap.timeline({
      // Animations are typically controlled by a parent component using ScrollTrigger.
      // This component sets the initial state and the animation itself.
      // The parent will trigger this timeline or individual elements.
      defaults: { ease: 'power2.out', duration: 1 },
    });

    // Animate the skill name fading in
    tl.to(skillNameRef.current, {
      opacity: 1,
      y: 0,
      duration: 0.8,
    });

    // Animate the progress bar filling up
    // We use `delay` here to make it appear after the name, creating a staggered effect within the component.
    // The overall stagger/triggering will be handled by the parent.
    tl.fromTo(
      progressOverlayRef.current,
      { width: 0 },
      { width: `${level}%` },
      0.3 // Start slightly after the name animation begins
    );

    // Initial state for GSAP to animate from
    gsap.set([skillNameRef.current, progressBarRef.current], {
      opacity: 0,
      y: 20,
    });

    // Return the timeline to be potentially managed by the parent's useScrollAnimation hook
    return () => {
      tl.kill();
    };
  }, [level]); // Re-run effect if level changes, though typically static data.

  return (
    <div className="skill-indicator-component relative w-full">
      <h4
        ref={skillNameRef}
        className="text-lg font-medium mb-2 text-gray-200"
        style={{ opacity: 0, y: 20 }} // Initial state for GSAP
      >
        {name}
      </h4>
      <div
        ref={progressBarRef}
        className="w-full h-3 bg-gray-700 rounded-full overflow-hidden shadow-inner"
        style={{ opacity: 0, y: 20 }} // Initial state for GSAP
      >
        <div
          ref={progressOverlayRef}
          className="h-full bg-gradient-to-r from-teal-400 to-blue-500 rounded-full"
          style={{ width: 0 }} // Initial width for GSAP animation
        ></div>
      </div>
      {/* Optional: Display level percentage */} 
      <span className="absolute top-0 right-0 text-sm text-gray-400 font-light">
