import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const ServiceCard = ({ icon: IconComponent, title, description }) => {
  const cardRef = useRef(null);

  useEffect(() => {
    const element = cardRef.current;
    if (!element) return;

    // Initial state for GSAP animation
    gsap.set(element, { y: 50, opacity: 0 });

    // Animation triggered by ScrollTrigger
    const animation = gsap.to(element, {
      y: 0,
      opacity: 1,
      duration: 1,
      ease: 'power2.out',
      scrollTrigger: {
        trigger: element,
        start: 'top 80%', // Adjust as needed for desired trigger point
        toggleActions: 'play none none none',
      },
    });

    // Cleanup on unmount
    return () => {
      animation.kill();
      // If ScrollTrigger instance is created directly here, kill it.
      // If managed by a parent hook like `useScrollAnimation`, this cleanup might not be needed.
    };
  }, []); // Empty dependency array ensures this runs once on mount

  return (
    <div
      ref={cardRef}
      className="bg-gray-800 bg-opacity-50 rounded-lg p-8 shadow-lg transition-shadow duration-300 hover:shadow-xl flex flex-col items-center text-center min-h-[300px] justify-center"
