import gsap from 'gsap';

const ContactForm = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null); // 'success' or 'error'

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name || !email || !message) {
      setSubmitStatus('error');
      // Optionally show a more specific error message
      return;
    }

    setIsSubmitting(true);
    setSubmitStatus(null);

    // In a real application, you would send this data to your backend API
    // For demonstration, we'll simulate a successful submission after a delay
    try {
      await new Promise(resolve => setTimeout(resolve, 1500)); // Simulate API call
      console.log('Form Submitted:', { name, email, message });
      setSubmitStatus('success');
      // Reset form fields
      setName('');
      setEmail('');
      setMessage('');
    } catch (error) {
      console.error('Form submission failed:', error);
      setSubmitStatus('error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // GSAP animation for form elements - typically orchestrated by the parent component (ContactPage)
  // This component focuses on its internal state and JSX structure.
  // The 'initialStyle' is provided as a fallback and for parent GSAP targeting.
  const initialStyle = {
    opacity: 0,
    y: 20,
  };

  return (
    <form onSubmit={handleSubmit} className="bg-gray-800 bg-opacity-60 p-8 rounded-lg shadow-xl space-y-6 max-w-lg mx-auto transform transition-all duration-500 ease-in-out hover:shadow-2xl">
      <h3 className="text-3xl font-bold text-center mb-8 text-transparent bg-clip-text bg-gradient-to-r from-teal-400 to-blue-500">Get In Touch</h3>

      <div className="space-y-4">
        <div>
          <label htmlFor="name" className="block text-sm font-medium text-gray-300 mb-1">Name</label>
          <input
            type="text"
            id="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            className="w-full px-4 py-3 rounded-lg bg-gray-700 border border-gray-600 placeholder-gray-400 text-white focus:outline-none focus:ring-2 focus:ring-teal-500 transition duration-200"
            style={initialStyle}
          />
        </div>
        <div>
          <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-1">Email</label>
          <input
            type="email"
            id="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="w-full px-4 py-3 rounded-lg bg-gray-700 border border-gray-600 placeholder-gray-400 text-white focus:outline-none focus:ring-2 focus:ring-teal-500 transition duration-200"
            style={initialStyle}
          />
        </div>
        <div>
          <label htmlFor="message" className="block text-sm font-medium text-gray-300 mb-1">Message</label>
          <textarea
            id="message"
            rows="5"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            required
            className="w-full px-4 py-3 rounded-lg bg-gray-700 border border-gray-600 placeholder-gray-400 text-white focus:outline-none focus:ring-2 focus:ring-teal-500 transition duration-200 resize-none"
            style={initialStyle}
          ></textarea>
        </div>
      </div>

      <button
        type="submit"
        disabled={isSubmitting}
        className="w-full px-6 py-3 bg-gradient-to-r from-teal-500 to-blue-600 rounded-lg text-white font-semibold shadow-md hover:from-teal-600 hover:to-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500 transition duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
        style={initialStyle}
      >
        {isSubmitting ? 'Sending...' : 'Send Message'}
      </button>

      {submitStatus === 'success' && (
        <p className="text-center text-green-400 mt-4">Message sent successfully!</p>
      )}
      {submitStatus === 'error' && (
        <p className="text-center text-red-400 mt-4">Something went wrong. Please try again.</p>
      )}
    </form>
  );
};

export default ContactForm;
