    "content": "import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

/**
 * Custom React hook for managing GSAP ScrollTrigger animations.
 *
 * @param {object} config - Configuration object for the hook.
 * @param {React.RefObject} config.triggerRef - Ref to the DOM element that triggers the animations.
 * @param {Array<object>} config.animations - Array of animation configurations.
 * @param {React.RefObject} config.animations[].elementRef - Ref to the DOM element to animate.
 * @param {object} config.animations[].animation - GSAP animation properties (e.g., { y: 50, opacity: 1 }).
 * @param {string} config.animations[].start - ScrollTrigger start position (e.g., 'top 80%').
 * @param {string} [config.animations[].end] - ScrollTrigger end position (optional).
 * @param {string} [config.animations[].scrub] - ScrollTrigger scrub value (optional).
 * @param {string} [config.animations[].toggleActions] - ScrollTrigger toggleActions value (optional).
 * @param {function} [config.onEnterViewport] - Callback function executed when the trigger enters the viewport.
 */
const useScrollAnimation = ({ triggerRef, animations, onEnterViewport }) => {
  const animationInstancesRef = useRef([]);

  useEffect(() => {
    const triggerElement = triggerRef.current;
    if (!triggerElement || !animations || animations.length === 0) {
      return;
    }

    const allScrollTriggers = [];

    const animateElements = (animConfig) => {
      const { elementRef, animation, start, end, scrub, toggleActions } = animConfig;
      const element = elementRef.current;

      if (element) {
        // Set initial state for GSAP animation
        gsap.set(element, { opacity: 0, y: 20 }); // Default initial state

        const scrollTriggerInstance = ScrollTrigger.create({
          trigger: triggerElement,
          start: start || 'top 80%', // Default start
          end: end || 'bottom 20%',   // Default end
          scrub: scrub,
          toggleActions: toggleActions || 'play none none none', // Default toggle actions
          onEnter: () => {
            gsap.to(element, {
              ...animation,
              opacity: 1,
              y: 0,
              onComplete: () => {
                // Remove inline styles after animation to allow CSS to take over if needed
                element.style.opacity = '';
                element.style.transform = '';
              }
            });
          },
          onEnterBack: () => {
            // Optionally play animation again when scrolling back up
            gsap.to(element, {
              ...animation,
              opacity: 1,
              y: 0,
              onComplete: () => {
                element.style.opacity = '';
                element.style.transform = '';
              }
            });
          },
          // Prevent multiple triggers if the same element is listed multiple times with different settings
          id: element.id || `${element.tagName}-${Math.random()}`
        });
        allScrollTriggers.push(scrollTriggerInstance);
      }
    };

    // Execute the onEnterViewport callback if provided, passing the animation function
    if (onEnterViewport) {
      onEnterViewport(animateElements);
    } else {
      // Otherwise, animate all provided animations directly
      animations.forEach(animConfig => {
        animateElements(animConfig);
      });
    }

    animationInstancesRef.current = allScrollTriggers;

    // Cleanup function to kill ScrollTriggers when the component unmounts
    return () => {
      allScrollTriggers.forEach(st => st.kill());
      animationInstancesRef.current = [];
    };

  }, [triggerRef, animations, onEnterViewport]); // Re-run effect if these props change

  // Optionally, you could return refs or other values here if needed by the consuming component
  return null;
};

export default useScrollAnimation;
