    "file_path": "src/hooks/useParallaxEffect.js",
    "content": "import { useEffect, useRef } from 'react';
import gsap from 'gsap';

/**
 * Custom React hook for implementing parallax scrolling effects on a DOM element.
 *
 * @param {React.RefObject} elementRef - A React ref object pointing to the DOM element to apply the parallax effect.
 * @param {object} options - Configuration options for the parallax effect.
 * @param {number} [options.speed=0.5] - The speed of the parallax effect. A value between 0 and 1 controls how much slower the element moves compared to the scroll.
 * @param {string} [options.direction='vertical'] - The direction of the parallax effect ('vertical' or 'horizontal').
 * @param {string} [options.startOffset='top bottom'] - The trigger start position for the parallax effect.
 * @param {string} [options.endOffset='bottom top'] - The trigger end position for the parallax effect.
 * @param {boolean} [options.isEnabled=true] - A flag to enable or disable the parallax effect.
 */
const useParallaxEffect = (elementRef, options = {}) => {
  const { speed = 0.5, direction = 'vertical', startOffset = 'top bottom', endOffset = 'bottom top', isEnabled = true } = options;
  const tl = useRef(null);
  const positionMultiplier = useRef(0);

  useEffect(() => {
    if (!elementRef.current || !isEnabled) {
      return;
    }

    const element = elementRef.current;

    // Determine the position multiplier based on direction
    if (direction === 'vertical') {
      positionMultiplier.current = speed;
    } else if (direction === 'horizontal') {
      positionMultiplier.current = speed;
    }

    // Set initial position if not already set by CSS
    gsap.set(element, {
      [direction === 'vertical' ? 'y' : 'x']: 0,
      willChange: 'transform',
    });

    // Create GSAP timeline for the parallax animation
    tl.current = gsap.timeline({
      scrollTrigger: {
        trigger: element,
        start: startOffset,
        end: endOffset,
        scrub: 1, // Smoothly animate based on scroll position
        invalidateOnRefresh: true, // Re-calculate on resize
      },
    });

    // Add the animation to the timeline
    if (direction === 'vertical') {
      tl.current.to(element, {
        y: () => window.innerHeight * positionMultiplier.current,
        ease: 'power1.out',
      });
    } else if (direction === 'horizontal') {
      tl.current.to(element, {
        x: () => window.innerWidth * positionMultiplier.current,
        ease: 'power1.out',
      });
    }

    // Cleanup function
    return () => {
      if (tl.current) {
        tl.current.kill();
        tl.current = null;
      }
      // Reset styles if necessary
      gsap.set(element, { willChange: 'auto' });
    };
  }, [elementRef, speed, direction, startOffset, endOffset, isEnabled]);

  // Return the timeline ref if you need to control it externally, otherwise null is fine
  return tl;
};

export default useParallaxEffect;
