const cleaned = [];
const empty = [];

// Track files by path
const fileMap = new Map();

for (const item of items) {
  const file = item.json;
  const path = file.file_path || "";
  const content = file.content;

  // Detect folder
  const isFolder = !path.includes(".");

  if (isFolder) continue; // skip folders entirely

  // Check empty
  const isEmpty =
    content === null ||
    content === undefined ||
    (typeof content === "string" && content.trim() === "");

  // If file already exists, resolve conflict
  if (fileMap.has(path)) {
    const existing = fileMap.get(path);

    // If existing is empty and new is non-empty → replace
    if (existing.isEmpty && !isEmpty) {
      fileMap.set(path, { path, content, isEmpty });
    }

    // If both empty or new is empty but existing non-empty → do nothing
    continue;
  }

  // Add new file
  fileMap.set(path, { path, content, isEmpty });
}

// Build final arrays
for (const entry of fileMap.values()) {
  if (entry.isEmpty) {
    empty.push({
      file_path: entry.path,
      content: entry.content
    });
  } else {
    cleaned.push({
      file_path: entry.path,
      content: entry.content
    });
  }
}

return [
  {
    json: {
      cleaned,
      empty,
      count_empty: empty.length
    }
  }
];

// n8n Function Node
// Input example: [{ file_path: "...", content: "..." }, ...]

// Step 1 — Create an empty object to collect all files
let output = {};

// Step 2 — Loop through all input items
for (const item of $input.first().json.cleaned) {
  const fp = item.file_path;
  const content = item.content ?? "";

  if (!fp) {
    throw new Error("Missing file_path in one of the items");
  }

  // Add to final object
  output[fp] = content;
}

// Step 3 — Return SINGLE n8n item
return [
  {
    json: output
  }
];

