    "content": "import React, { useState, useEffect } from 'react';
import { Link as ScrollLink } from 'react-scroll';
import { useLocation, useNavigate } from 'react-router-dom';

const Navbar = () => {
  const [activeSection, setActiveSection] = useState('');
  const location = useLocation();
  const navigate = useNavigate();

  const navItems = [
    { id: 'home', name: 'Home' },
    { id: 'about', name: 'About' },
    { id: 'services', name: 'Services' },
    { id: 'contact', name: 'Contact' },
  ];

  useEffect(() => {
    // If we are on the homepage, handle scroll-based active section
    if (location.pathname === '/') {
      const handleScroll = () => {
        const sections = document.querySelectorAll('section[id]');
        let currentSection = '';
        sections.forEach((section) => {
          const sectionTop = section.offsetTop - 50; // Adjust for navbar height
          if (window.scrollY >= sectionTop) {
            currentSection = section.getAttribute('id');
          }
        });
        setActiveSection(currentSection);
      };

      window.addEventListener('scroll', handleScroll);
      return () => window.removeEventListener('scroll', handleScroll);
    } else {
      // If not on homepage, reset active section
      setActiveSection('');
    }
  }, [location]);

  const handleNavClick = (sectionId) => {
    if (location.pathname !== '/') {
      navigate('/');
      // Use setTimeout to allow route change before attempting to scroll
      setTimeout(() => {
        const element = document.getElementById(sectionId);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        }
      }, 100); // Small delay to ensure the DOM is updated after navigation
    } else {
      const element = document.getElementById(sectionId);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  return (
    <nav className="sticky top-0 z-50 w-full bg-white dark:bg-gray-900 shadow-md py-4 px-6 transition-colors duration-300">
      <div className="container mx-auto flex justify-between items-center">
        <div className="text-2xl font-bold text-blue-600 dark:text-blue-400 cursor-pointer"
             onClick={() => handleNavClick('home')}>
          YourLogo
        </div>
        <ul className="hidden md:flex space-x-8">
          {navItems.map((item) => (
            <li key={item.id}>
              <ScrollLink
                to={item.id}
                spy={true}
                smooth={true}
                offset={-80} // Adjust scroll offset for navbar height
                duration={500}
                onClick={() => handleNavClick(item.id)}
                className={`text-lg font-medium cursor-pointer transition-colors duration-300
                          ${activeSection === item.id
                            ? 'text-blue-600 dark:text-blue-400 border-b-2 border-blue-600 dark:border-blue-400 pb-1'
                            : 'text-gray-700 dark:text-gray-300 hover:text-blue-500 dark:hover:text-blue-300'}`}
              >
                {item.name}
              </ScrollLink>
            </li>
          ))}
        </ul>
        {/* Mobile Menu Button (Hamburger) - Implementation omitted for brevity */}
        <div className="md:hidden">
          <button className="text-gray-700 dark:text-gray-300 focus:outline-none">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7"></path></svg>
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
