    "content": "import React, { useRef, useEffect } from 'react';
import gsap from 'gsap';

const SkillProgressIndicator = ({ name, progress }) => {
  const progressRef = useRef(null);
  const progressValueRef = useRef(null);

  // This component relies on its parent to trigger the animation via ScrollTrigger.
  // The actual animation logic will be handled by the parent using a ref and GSAP.
  // We are setting up the initial state and the refs here.

  useEffect(() => {
    // Ensure progress is within bounds
    const validProgress = Math.max(0, Math.min(100, progress));

    // This effect is primarily for setting the initial state
    // The actual animation will be called from the parent component's ScrollTrigger setup.
    if (progressRef.current) {
      progressRef.current.style.width = '0%'; // Start at 0% for animation
      progressRef.current.setAttribute('aria-valuenow', validProgress);
    }
    if (progressValueRef.current) {
      progressValueRef.current.textContent = '0%';
    }
  }, [progress]);

  // Function to be called by the parent to animate the progress bar
  const animateProgress = () => {
    const validProgress = Math.max(0, Math.min(100, progress));

    if (progressRef.current && progressValueRef.current) {
      gsap.to(progressRef.current, {
        width: `${validProgress}%`,
        duration: 1.2,
        ease: 'power2.out',
        onUpdate: () => {
          // Update text content during animation
          progressValueRef.current.textContent = Math.round(progressRef.current.offsetWidth / progressRef.current.parentElement.offsetWidth * 100) + '%';
        },
        onComplete: () => {
          // Ensure the text is exactly the final progress value on completion
          progressValueRef.current.textContent = `${validProgress}%`;
        }
      });
    }
  };

  // Expose the animate function to the parent component via a ref
  React.useImperativeHandle(progressRef, () => ({
    animate: animateProgress
  }));

  return (
    <div className="flex items-center justify-between mb-2">
      <span className="text-base font-medium text-gray-700 dark:text-gray-300 w-1/3">{name}</span>
      <div className="w-2/3 bg-gray-200 rounded-full h-4 dark:bg-gray-700 relative">
        <div 
          ref={progressRef}
          className="bg-blue-600 h-4 rounded-full transition-all duration-500 ease-out"
          style={{ width: '0%' }} // Initial width set to 0 for GSAP animation
          role="progressbar" 
          aria-valuemin="0" 
          aria-valuemax="100"
        ></div>
        <span 
          ref={progressValueRef} 
          className="absolute inset-y-0 right-2 flex items-center text-xs font-medium text-gray-900 dark:text-white"
        >0%</span>
      </div>
    </div>
  );
};

export default SkillProgressIndicator;
