    "content": "import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

/**
 * Custom React hook to implement parallax scrolling effects on a target element.
 *
 * @param {React.RefObject<HTMLElement>} elementRef - A ref object pointing to the DOM element to apply the parallax effect.
 * @param {object} [options={}] - Configuration options for the parallax effect.
 * @param {number} [options.speed=0.5] - The speed multiplier for the parallax effect. Higher values mean faster movement (less parallax).
 * @param {string} [options.start='top bottom'] - The scroll start position (GSAP ScrollTrigger format).
 * @param {string} [options.end='bottom top'] - The scroll end position (GSAP ScrollTrigger format).
 * @param {boolean} [options.scale=false] - Whether to apply a scale effect along with the translate.
 * @param {number} [options.scaleAmount=0.2] - The amount to scale if scale is true.
 * @param {string} [options.animationDirection='translateY'] - The CSS property to animate ('translateY' or 'translateX').
 */
const useParallaxEffect = (elementRef, options = {}) => {
  const { 
    speed = 0.5,
    start = 'top bottom',
    end = 'bottom top',
    scale = false,
    scaleAmount = 0.2,
    animationDirection = 'translateY'
  } = options;

  const parallaxAnimationRef = useRef(null);

  useEffect(() => {
    if (elementRef.current) {
      const element = elementRef.current;
      const bounds = element.getBoundingClientRect();
      const elementHeight = bounds.height;
      const viewportHeight = window.innerHeight;

      // Calculate the distance to move based on speed and element/viewport height
      // This calculation aims to move the element by a certain factor of the viewport height as it scrolls past.
      const moveDistance = (viewportHeight * speed);

      // GSAP animation configuration
      const animationConfig = {
        trigger: element,
        start: start,
        end: end,
        scrub: 1, // Smoothly scrub the animation as the user scrolls
        markers: false // Set to true for debugging ScrollTrigger
      };

      const tweenConfig = {
        [animationDirection]: moveDistance,
        ease: 'none',
      };

      if (scale) {
        tweenConfig.scale = 1 - scaleAmount;
      }

      // Cleanup previous animation if it exists
      if (parallaxAnimationRef.current) {
        parallaxAnimationRef.current.kill();
      }

      // Create and play the GSAP animation
      parallaxAnimationRef.current = gsap.to(element, {
        ...tweenConfig,
        scrollTrigger: animationConfig
      });
    }

    // Cleanup ScrollTrigger instance on unmount
    return () => {
      if (parallaxAnimationRef.current) {
        parallaxAnimationRef.current.kill();
      }
    };
  }, [elementRef, speed, start, end, scale, scaleAmount, animationDirection]); // Re-run effect if any dependency changes

  // No return value needed, the hook applies the effect directly
};

export default useParallaxEffect;
