    "content": "import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

/**
 * A custom React hook that encapsulates the logic for creating GSAP ScrollTrigger-based animations.
 * It accepts a ref to the target element(s) and an animation configuration to trigger specific animations.
 *
 * @param {HTMLElement | HTMLElement[] | null} targets - The DOM element(s) to animate. Can be a single element, an array of elements, or null.
 * @param {object} config - The ScrollTrigger configuration object, including animation details.
 * @param {string | function(): string} config.trigger - The element that triggers the animation.
 * @param {string} config.start - The start position for the trigger (e.g., 'top center').
 * @param {string} [config.end] - The end position for the trigger.
 * @param {string} [config.scrub] - Enables smooth scrubbing of the animation.
 * @param {function(HTMLElement, number): void} config.animation - A function that defines the GSAP animation to apply to each target. Receives the target element and its index.
 * @param {object} [config.gsapDefaults={}] - Default GSAP tween properties to apply.
 */
const useScrollTriggeredAnimation = (targets, config) => {
  const { trigger, start, end, scrub, animation, gsapDefaults = {} } = config;
  const scrollTriggerInstance = useRef(null);

  useEffect(() => {
    if (!targets) {
      return;
    }

    const elements = Array.isArray(targets) ? targets : [targets];

    // Ensure ScrollTrigger is registered (though it's done globally too)
    if (!ScrollTrigger) {
      gsap.registerPlugin(ScrollTrigger);
    }

    // Create a ScrollTrigger instance
    scrollTriggerInstance.current = ScrollTrigger.create({
      trigger: trigger || elements[0], // Use the first element if trigger is not specified
      start: start,
      end: end || '+=300',
      scrub: scrub,
      markers: false, // Set to true for debugging
      onEnter: () => {
        elements.forEach((element, index) => {
          if (element) {
            // Call the provided animation function for each target element
            animation(element, index, gsapDefaults);
          }
        });
      },
      onEnterBack: () => {
        // Optionally re-animate when scrolling back up
        elements.forEach((element, index) => {
          if (element) {
            animation(element, index, gsapDefaults);
          }
        });
      },
      // Add other ScrollTrigger callbacks if needed (e.g., onLeave, onLeaveBack)
    });

    // Cleanup function to kill the ScrollTrigger instance when the component unmounts
    return () => {
      if (scrollTriggerInstance.current) {
        scrollTriggerInstance.current.kill();
      }
    };
    // Depend on elements to re-create the trigger if the targets change.
    // Note: Deep comparison of elements array might be needed for complex cases.
  }, [targets, trigger, start, end, scrub, animation, JSON.stringify(gsapDefaults)]);

  // The hook doesn't return anything, it applies the animation side effect.
};

export default useScrollTriggeredAnimation;
