    "content": "import React, { createContext, useState, useContext, useEffect, useRef } from 'react';
import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const ActiveSectionContext = createContext();

export const useActiveSection = () => {
  return useContext(ActiveSectionContext);
};

export const ActiveSectionProvider = ({ children }) => {
  const [activeSection, setActiveSection] = useState('');
  const sectionRefs = useRef({});

  useEffect(() => {
    // Ensure ScrollTrigger is registered
    if (!ScrollTrigger) {
      gsap.registerPlugin(ScrollTrigger);
    }

    const sections = document.querySelectorAll('section[id]');
    const triggers = [];

    sections.forEach((section) => {
      const sectionId = section.getAttribute('id');
      sectionRefs.current[sectionId] = section;

      const trigger = ScrollTrigger.create({
        trigger: section,
        start: 'top 80%', // Start when the top of the section reaches 80% of the viewport height
        end: 'bottom 20%', // End when the bottom of the section reaches 20% of the viewport height
        markers: false, // Set to true for debugging
        onEnter: () => setActiveSection(sectionId),
        onEnterBack: () => setActiveSection(sectionId),
        // Adjusting onLeave and onLeaveBack to correctly update active section when scrolling rapidly
        onLeave: () => {
          // If scrolling up and leaving a section, the previous section might become active
          // We need to find the section above the current one.
          const currentSectionIndex = Array.from(sections).findIndex(s => s.id === sectionId);
          if (currentSectionIndex > 0) {
            // Check if we are truly leaving it and not just entering the next one
            if (window.scrollY < section.offsetTop) {
              setActiveSection(sections[currentSectionIndex - 1].id);
            }
          }
        },
        onLeaveBack: () => {
          // If scrolling down and leaving a section (going back up), the section above becomes active.
          const currentSectionIndex = Array.from(sections).findIndex(s => s.id === sectionId);
          if (currentSectionIndex > 0) {
            setActiveSection(sections[currentSectionIndex - 1].id);
          } else {
            // If it's the first section, clear active section or set to default
            setActiveSection('');
          }
        }
      });
      triggers.push(trigger);
    });

    // Initial check to set the active section on load if the user starts scrolled down
    let currentSection = '';
    sections.forEach((section) => {
      const sectionTop = section.offsetTop - 50; // Adjust for navbar height
      if (window.scrollY >= sectionTop) {
        currentSection = section.getAttribute('id');
      }
    });
    setActiveSection(currentSection);

    // Cleanup ScrollTriggers on unmount
    return () => {
      triggers.forEach(trigger => trigger.kill());
    };
  }, []); // Empty dependency array ensures this effect runs only once on mount

  return (
    <ActiveSectionContext.Provider value={{ activeSection, setActiveSection }}>
      {children}
    </ActiveSectionContext.Provider>
  );
};
