    "file_path": "src/lib/animations/animations.js",
    "content": "import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

/**
 * Animates the initial fade-in and slide-up of hero text.
 * @param {string | HTMLElement} element - The target element or selector.
 * @param {object} [options={}] - GSAP tween options.
 */
export const animateHeroText = (element, options = {}) => {
  gsap.fromTo(element, 
    { opacity: 0, y: 50 }, 
    { opacity: 1, y: 0, duration: 1, ease: 'power2.out', ...options }
  );
};

/**
 * Animates the fade-in of subtitle text with a delay.
 * @param {string | HTMLElement} element - The target element or selector.
 * @param {object} [options={}] - GSAP tween options.
 */
export const animateSubtitle = (element, options = {}) => {
  gsap.fromTo(element, 
    { opacity: 0 }, 
    { opacity: 1, duration: 0.8, delay: 0.5, ease: 'power2.out', ...options }
  );
};

/**
 * Creates a staggered fade-in animation for a list of elements.
 * @param {string | string[] | HTMLElement[]} elements - The target elements or selectors.
 * @param {object} [options={}] - GSAP tween options.
 */
export const staggerFadeIn = (elements, options = {}) => {
  gsap.fromTo(elements, 
    { opacity: 0, y: 30 }, 
    { opacity: 1, y: 0, duration: 0.8, stagger: 0.2, ease: 'power2.out', ...options }
  );
};

/**
 * Animates the width of a progress bar from 0 to its target value.
 * @param {string | HTMLElement} element - The target progress bar element.
 * @param {number} targetWidth - The target width percentage (0-100).
 * @param {object} [options={}] - GSAP tween options.
 */
export const animateProgressBar = (element, targetWidth, options = {}) => {
  gsap.to(element, {
    width: `${targetWidth}%`,
    duration: 1.2,
    ease: 'power2.out',
    ...options,
  });
};

/**
 * Animates a section's elements with a fade and upward motion when scrolled into view.
 * @param {string | string[] | HTMLElement[]} elements - The target elements or selectors.
 * @param {object} [config={}] - GSAP ScrollTrigger configuration.
 * @param {string | HTMLElement} config.trigger - The element that triggers the animation.
 * @param {string} config.start - The scroll start position.
 * @param {object} [config.gsapOptions={}] - Additional GSAP tween options.
 */
export const animateSectionOnScroll = (elements, config = {}) => {
  const { trigger, start, gsapOptions = {} } = config;

  gsap.fromTo(elements, 
    { opacity: 0, y: 50 }, 
    {
      opacity: 1,
      y: 0,
      duration: 0.8,
      stagger: 0.15,
      ease: 'power2.out',
      scrollTrigger: {
        trigger: trigger || (Array.isArray(elements) ? elements[0] : elements),
        start: start || 'top 80%',
        end: 'bottom 60%',
        scrub: false, // Set to true for scrubbing animation
        once: true, // Only animate once
        ...gsapOptions.scrollTrigger
      },
      ...gsapOptions
    }
  );
};

/**
 * Scales up an element from a smaller size.
 * @param {string | HTMLElement} element - The target element or selector.
 * @param {object} [options={}] - GSAP tween options.
 */
export const scaleUp = (element, options = {}) => {
  gsap.fromTo(element, 
    { scale: 0.8, opacity: 0 }, 
    { scale: 1, opacity: 1, duration: 1, ease: 'power2.out', ...options }
  );
};

/**
 * Creates a smooth scroll animation to a target element.
 * @param {string | HTMLElement} target - The target element or selector to scroll to.
 * @param {object} [options={}] - GSAP ScrollToPlugin options.
 */
export const scrollToElement = (target, options = {}) => {
  gsap.to(window, {
    scrollTo: target,
    duration: 1,
    ease: 'power2.out',
    ...options
  });
};

/**
 * Basic stagger animation for cards.
 * @param {string | HTMLElement[]} elements - The target card elements.
 * @param {object} [options={}] - GSAP tween options.
 */
export const staggerCardAnimation = (elements, options = {}) => {
  gsap.fromTo(elements, 
    { opacity: 0, scale: 0.95 }, 
    { opacity: 1, scale: 1, duration: 0.6, stagger: 0.2, ease: 'power2.out', ...options }
  );
};

/**
 * Animates contact form fields fading and sliding in.
 * @param {string | HTMLElement[]} fields - The form field elements.
 * @param {object} [options={}] - GSAP tween options.
 */
export const animateFormFields = (fields, options = {}) => {
  gsap.fromTo(fields, 
    { opacity: 0, y: 20 }, 
