import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';
import ServiceCard from '../components/sections/Services/ServiceCard';
import { useScrollTriggeredAnimation } from '../hooks/useScrollTriggeredAnimation';

// Import icons using SVGR or similar if configured, otherwise use placeholder
import { FaCode, FaPaintBrush, FaServer, FaRocket, FaCloud, FaCog } from 'react-icons/fa';

gsap.registerPlugin(ScrollTrigger);

const ServicesPage = ({ id }) => {
  const servicesContainerRef = useRef(null);
  const serviceCardsRefs = useRef([]);

  const services = [
    { icon: FaCode, title: 'Web Development', description: 'Building modern, responsive, and scalable web applications using the latest technologies.' },
    { icon: FaPaintBrush, title: 'UI/UX Design', description: 'Crafting intuitive and engaging user interfaces with a focus on user experience and visual appeal.' },
    { icon: FaServer, title: 'Backend Development', description: 'Developing robust and efficient server-side logic and APIs to power your applications.' },
    { icon: FaRocket, title: 'Performance Optimization', description: 'Enhancing website speed and performance for a seamless user experience.' },
    { icon: FaCloud, title: 'Cloud Solutions', description: 'Leveraging cloud platforms for scalable and reliable hosting and infrastructure.' },
    { icon: FaCog, title: 'Consulting Services', description: 'Providing expert advice and strategic guidance for your digital projects.' },
  ];

  // Effect to capture refs for each service card
  useEffect(() => {
    if (servicesContainerRef.current) {
      serviceCardsRefs.current = Array.from(servicesContainerRef.current.children);
    }
  }, [services]);

  // Animation for service cards
  useScrollTriggeredAnimation(serviceCardsRefs.current, {
    trigger: servicesContainerRef.current,
    start: 'top 85%',
    animation: (element, index) => {
      gsap.fromTo(element, 
        { opacity: 0, y: 50 }, 
        { opacity: 1, y: 0, duration: 0.8, stagger: 0.15, ease: 'power2.out' })
    }
  });

  return (
    <section id={id} className="py-16 md:py-24 bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-200">
