              icon={service.icon}
              title={service.title}
              description={service.description}
              index={index} // Pass index for staggered animation
              // triggerAnimation={true} // The useScrollTriggeredAnimation hook handles the trigger
            />
          ))}
        </div>
      </div>
    </section>
  );
};

