    "content": "import React, { useState, useRef } from 'react';
import Input from '../ui/Input';
import Textarea from '../ui/Textarea';
import Button from '../ui/Button';
import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const ContactForm = React.forwardRef((props, ref) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
  });

  const [errors, setErrors] = useState({});
  const formRef = useRef(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({ ...prevState, [name]: value }));
    // Clear error for the current field when user starts typing
    if (errors[name]) {
      setErrors(prevErrors => ({
        ...prevErrors,
        [name]: '',
      }));
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }
    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\[^@]+@[^\]+\.\[^@\]+/.test(formData.email)) {
      newErrors.email = 'Email address is invalid';
    }
    if (!formData.message.trim()) {
      newErrors.message = 'Message is required';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (validateForm()) {
      // Simulate form submission with GSAP animation
      // In a real application, you would send this data to a backend API
      console.log('Form Data:', formData);

      // Example success animation
      gsap.to(formRef.current, {
        opacity: 0,
        y: 50,
        duration: 0.5,
        onComplete: () => {
          alert('Message sent successfully! (Simulated)');
          setFormData({ name: '', email: '', message: '' }); // Reset form
          gsap.fromTo(formRef.current, 
            { opacity: 0, y: -50 }, 
            { opacity: 1, y: 0, duration: 0.8, ease: 'power2.out' }); // Re-appear form
        }
      });
    }
  };

  // Use refs passed from the parent component (ContactPage)
  const nameInputRef = ref && ref.current && ref.current[0] ? ref.current[0] : useRef(null);
  const emailInputRef = ref && ref.current && ref.current[1] ? ref.current[1] : useRef(null);
  const messageTextareaRef = ref && ref.current && ref.current[2] ? ref.current[2] : useRef(null);
  const submitButtonRef = ref && ref.current && ref.current[3] ? ref.current[3] : useRef(null);

  return (
    <form ref={formRef} onSubmit={handleSubmit} className="bg-white dark:bg-gray-800 shadow-lg rounded-lg p-8">
      <h3 className="text-3xl font-bold text-center mb-6 text-gray-800 dark:text-gray-200">Send a message</h3>
      <p className="text-center text-gray-600 dark:text-gray-300 mb-8">Have a question or want to work together? Just send me a message!</p>

      <Input
        ref={nameInputRef}
        label="Your Name"
        name="name"
        type="text"
        placeholder="Enter your name"
        value={formData.name}
        onChange={handleChange}
        error={errors.name}
      />
      <Input
        ref={emailInputRef}
        label="Your Email"
        name="email"
        type="email"
        placeholder="Enter your email"
        value={formData.email}
        onChange={handleChange}
        error={errors.email}
      />
      <Textarea
        ref={messageTextareaRef}
        label="Your Message"
        name="message"
        placeholder="Your message here..."
        value={formData.message}
        onChange={handleChange}
        rows={5}
        error={errors.message}
      />
      <Button
        ref={submitButtonRef}
        type="submit"
        className="w-full mt-4 py-3 text-lg"
      >
        Send Message
      </Button>
    </form>
  );
});

ContactForm.displayName = 'ContactForm';
export default ContactForm;
