  useEffect(() => {
    // GSAP animations for hero content
    const tl = gsap.timeline({ defaults: { duration: 1, ease: 'power2.out' } });

    // Animate background initially (if needed, otherwise parallax handles it)
    gsap.fromTo(backgroundRef.current, { opacity: 0.8 }, { opacity: 1, duration: 1.5, ease: 'power2.inOut' });

