zip_buffer = io.BytesIO(zip_bytes)

# Insert file into nested dict
def insert_into_dict(struct, path_parts, content):
    key = path_parts[0]
    if len(path_parts) == 1:
        struct[key] = content
    else:
        if key not in struct:
            struct[key] = {}
        insert_into_dict(struct[key], path_parts[1:], content)

project_json = {}

# Read zip file
with zipfile.ZipFile(zip_buffer, "r") as zipf:
    for filepath in zipf.namelist():
        # Ignore directories
        if filepath.endswith("/"):
            continue

        data = zipf.read(filepath).decode("utf-8", errors="ignore")
        insert_into_dict(project_json, filepath.split("/"), data)

return [
    {
        "json": project_json
    }
]

