    "src/pages/ProductsPage.jsx": "import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import ItemCard from '../components/ItemCard';
import FilterSidebar from '../components/FilterSidebar';
import Pagination from '../components/Pagination';
import SkeletonLoader from '../components/SkeletonLoader';
import SortingOptions from '../components/SortingOptions';
import { gsap } from 'gsap';

const ProductsPage = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sortBy, setSortBy] = useState('');
  const [filters, setFilters] = useState({}); // e.g., { category: 'shoes', size: 'M' }

  const itemsPerPage = 12;
  const location = useLocation();
  const navigate = useNavigate();

  // Function to parse query parameters
  const getQueryParams = (location) => {
    const params = new URLSearchParams(location.search);
    const currentPageParam = parseInt(params.get('page') || '1', 10);
    const sortByParam = params.get('sort') || '';
    // You would parse other filter params here as well
    return { page: currentPageParam, sort: sortByParam };
  };

  useEffect(() => {
    // GSAP Page Transition Animation
    gsap.fromTo(
      'body', // Target the body element or a specific wrapper
      { opacity: 0, x: 50 },
      { opacity: 1, x: 0, duration: 0.5, ease: 'power2.out' }
    );

    const params = getQueryParams(location);
    setCurrentPage(params.page);
    setSortBy(params.sort);

    const fetchProducts = async () => {
      setLoading(true);
      setError(null);
      try {
        // Construct API URL with current filters and pagination
        const queryParams = new URLSearchParams({
          page: params.page.toString(),
          limit: itemsPerPage.toString(),
          sort: sortBy || params.sort || '',
          // Add other filter params here: 
          // ...Object.entries(filters).map(([key, value]) => [key, value])
        });

        // Replace with actual API call: const response = await fetch(`/api/products?${queryParams}`);
        await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate network delay

        // Mock API response structure
        const mockResponse = {
          products: Array.from({ length: itemsPerPage }, (_, i) => {
            const productId = (params.page - 1) * itemsPerPage + i + 1;
            return {
              id: `p${productId}`,
              name: `Product Name ${productId}`,
              price: (10 + productId * 1.5).toFixed(2),
              thumbnailUrl: `https://via.placeholder.com/300x200/f0f0f0/333333?text=Product+${productId}`,
              category: ['Shoes', 'Apparel', 'Accessories'][i % 3],
            };
          }),
          total: 100, // Mock total products
        };

        setProducts(mockResponse.products);
        setTotalPages(Math.ceil(mockResponse.total / itemsPerPage));
      } catch (err) {
        setError("Failed to load products.");
        console.error("Error fetching products:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, [location.search, sortBy, filters]); // Re-fetch when query params or filters change

  // Handler for page changes
  const handlePageChange = (page) => {
    const currentParams = new URLSearchParams(location.search);
    currentParams.set('page', page.toString());
    navigate(`?${currentParams.toString()}`);
  };

  // Handler for sort changes
  const handleSortChange = (selectedSort) => {
    setSortBy(selectedSort);
    const currentParams = new URLSearchParams(location.search);
    currentParams.set('sort', selectedSort);
    currentParams.set('page', '1'); // Reset to first page on sort change
    navigate(`?${currentParams.toString()}`);
  };

  // Handler for filter changes (would update 'filters' state and trigger fetch)
  const handleFilterChange = (newFilters) => {
    setFilters(newFilters);
    const currentParams = new URLSearchParams(location.search);
    // Update params based on newFilters
    currentParams.set('page', '1'); // Reset to first page on filter change
    navigate(`?${currentParams.toString()}`);
  };

  // Placeholder for Skeleton Loading
  const renderSkeletonLoaders = () => (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {[...Array(itemsPerPage)].map((_, index) => (
        <SkeletonLoader key={index} type="item-card" />
      ))}
    </div>
  );

  if (loading) {
    return (
      <div className="flex flex-col md:flex-row gap-8 p-4 md:p-8">
        <div className="w-full md:w-1/4 lg:w-1/5">
          <SkeletonLoader type="filter-sidebar" />
        </div>
        <div className="flex-1">
          {renderSkeletonLoaders()}
          <SkeletonLoader type="pagination" className="mt-8" />
        </div>
      </div>
    );
  }

  if (error) {
    return <div className="text-red-500 text-center py-10">{error}</div>;
  }

  return (
    <div className="flex flex-col md:flex-row gap-8 p-4 md:p-8">
      <div className="w-full md:w-1/4 lg:w-1/5">
        <FilterSidebar onFilterChange={handleFilterChange} />
      </div>
      <div className="flex-1">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold">Products</h1>
          <SortingOptions sortBy={sortBy} onSortChange={handleSortChange} />
        </div>
        {products.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
            {products.map(product => (
              <ItemCard
                key={product.id}
                id={product.id}
                name={product.name}
                price={product.price}
                thumbnailUrl={product.thumbnailUrl}
                category={product.category}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-10 text-gray-500 dark:text-gray-400">
            No products found matching your criteria.
          </div>
        )}
        {totalPages > 1 && (
          <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={handlePageChange} />
        )}
      </div>
    </div>
  );
};

export default ProductsPage;
