    "src/components/Button.jsx": "import React from 'react';

const Button = ({ children, onClick, type = 'button', className = '', disabled = false, ...props }) => {
  const baseStyles = "px-4 py-2 font-semibold rounded-lg focus:outline-none focus:ring-2 focus:ring-offset-2 transition duration-300 ease-in-out";

  const disabledStyles = "opacity-50 cursor-not-allowed";

  const primaryStyles = "bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500";
  const secondaryStyles = "bg-gray-200 text-gray-800 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600 focus:ring-gray-500";
  const outlinedStyles = "border-2 border-blue-600 text-blue-600 hover:bg-blue-50 focus:ring-blue-600";

  // Basic logic to determine styles - could be expanded with more variants
  const determineStyles = () => {
    if (className.includes('bg-gray')) return secondaryStyles;
    if (className.includes('border-blue')) return outlinedStyles;
    return primaryStyles;
  };

  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className={`${baseStyles} ${determineStyles()} ${disabled ? disabledStyles : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;
