    "src/components/Modal.jsx": "import React, { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { gsap } from 'gsap';

const Modal = ({ isOpen, onClose, children, title }) => {
  const modalRef = useRef(null);

  // Effect for handling Escape key press to close the modal
  useEffect(() => {
    const handleEscape = (event) => {
      if (event.key === 'Escape' && isOpen) {
        onClose();
      }
    };
    document.addEventListener('keydown', handleEscape);
    return () => {
      document.removeEventListener('keydown', handleEscape);
    };
  }, [isOpen, onClose]);

  // Effect for animating modal open/close
  useEffect(() => {
    if (isOpen) {
      // Fade in and scale up the modal content
      gsap.to(modalRef.current, {
        opacity: 1,
        scale: 1,
        duration: 0.4,
        ease: 'power2.out',
        onComplete: () => {
          // Ensure element is visible after animation
          if (modalRef.current) {
            modalRef.current.style.opacity = '1';
            modalRef.current.style.transform = 'scale(1)';
          }
        }
      });
    } else {
      // Fade out and scale down the modal content
      gsap.to(modalRef.current, {
        opacity: 0,
        scale: 0.95,
        duration: 0.3,
        ease: 'power2.in',
        onComplete: () => {
          // Ensure element is hidden after animation if needed, though CSS handles display
        }
      });
    }
  }, [isOpen]);

  const handleOverlayClick = (event) => {
    // Close modal if clicking on the overlay and not the content itself
    if (modalRef.current && !modalRef.current.contains(event.target)) {
      onClose();
    }
  };

  // Render modal only if isOpen is true, using createPortal for better DOM management
  if (!isOpen) {
    return null;
  }

  return createPortal(
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center overflow-auto bg-black bg-opacity-60 transition-opacity duration-300"
      onClick={handleOverlayClick}
      style={{ opacity: 0 }} // Initial state for GSAP animation
      ref={modalRef}
    >
      <div 
        className="relative bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 max-w-lg w-full transform scale-95 opacity-0 transition-all duration-300 ease-in-out"
        style={{ transform: 'scale(0.95)', opacity: 0 }} // Initial state for GSAP animation
      >
        {/* Modal Header */}
        <div className="flex justify-between items-center mb-4 pb-3 border-b border-gray-200 dark:border-gray-700">
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">{title || 'Modal'}</h2>
          <button 
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 dark:text-gray-500 dark:hover:text-gray-300 focus:outline-none"
            aria-label="Close modal"
          >
            <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        </div>

        {/* Modal Content */}
        <div className="modal-content">
          {children}
        </div>
      </div>
    </div>,
    document.body // Portal to body to avoid DOM hierarchy issues
  );
};

export default Modal;
