    "src/components/AddToCartButton.jsx": "import React from 'react';
import Button from './Button';
import { useCart } from '../hooks/useCart'; // Assuming a cart context/hook exists

const AddToCartButton = ({ product, selectedSize, selectedColor, quantity }) => {
  const { addToCart } = useCart(); // Get the function to add items to the cart

  const handleAddToCartClick = () => {
    if (!product || !selectedSize || !selectedColor || quantity <= 0) {
      console.warn('Cannot add to cart: Missing product details, size, color, or quantity.');
      alert('Please select size, color, and a valid quantity.'); // User feedback
      return;
    }

    // Prepare the item to be added to the cart
    const cartItem = {
      id: product.id,
      name: product.name,
      price: product.price,
      size: selectedSize,
      color: selectedColor,
      quantity: quantity,
      thumbnailUrl: product.thumbnailUrl, // Include thumbnail for cart display
    };

    addToCart(cartItem);
    alert(`${product.name} added to cart!`); // User feedback
  };

  return (
    <Button 
      onClick={handleAddToCartClick}
      className="w-full"
      disabled={!product || !selectedSize || !selectedColor || quantity <= 0} // Disable if essential info is missing
    >
      Add to Cart
    </Button>
  );
};

export default AddToCartButton;
