    "src/hooks/useFetch.js": "import { useState, useEffect, useCallback } from 'react';
import axios from 'axios'; // Assuming axios is used for API requests

const useFetch = (url, options = {}) => {
  const { method = 'get', params, data, headers, immediate = true, cacheDuration = 0, ...axiosOptions } = options;
  const [response, setResponse] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(immediate);
  const [abortController, setAbortController] = useState(null);
  // Simple cache implementation
  const [cache, setCache] = useState({});

  const fetchData = useCallback(async (fetchUrl = url) => {
    if (!fetchUrl) {
      setLoading(false);
      return;
    }

    // Check cache first
    if (cacheDuration > 0 && cache[fetchUrl] && cache[fetchUrl].timestamp > Date.now() - cacheDuration * 1000) {
      setResponse(cache[fetchUrl].data);
      setLoading(false);
      return;
    }

    // Cancel previous request if it exists
    if (abortController) {
      abortController.abort();
    }

    const controller = new AbortController();
    setAbortController(controller);

    setLoading(true);
    setError(null);

    try {
      const config = {
        method,
        url: fetchUrl,
        params: params,
        data: data,
        headers: { ...headers },
        signal: controller.signal,
        ...axiosOptions,
      };

      const result = await axios(config);
      const fetchedData = result.data;

      setResponse(fetchedData);

      // Update cache if cacheDuration is set
      if (cacheDuration > 0) {
        setCache({
          ...cache,
          [fetchUrl]: { data: fetchedData, timestamp: Date.now() },
        });
      }

    } catch (err) {
      if (err.name === 'AbortError') {
        console.log('Fetch aborted');
      } else {
        setError(err);
        // Potentially implement retry logic here based on err.response.status etc.
      }
    } finally {
      setLoading(false);
      // Clear the abort controller once the request is complete or aborted
      setAbortController(null);
    }
  }, [url, method, params, data, headers, cacheDuration, cache]); // Dependencies for useCallback

  // Effect to trigger fetch immediately if immediate is true
  useEffect(() => {
    if (immediate) {
      fetchData();
    }
    // Cleanup function to abort any ongoing request when the component unmounts
    return () => {
      if (abortController) {
        abortController.abort();
      }
    };
  }, [fetchData, immediate]); // Re-run if fetchData or immediate changes

  // Function to refetch data manually
  const refetch = useCallback(() => {
    fetchData(url); // Pass the original URL to fetchData
  }, [fetchData, url]);

  return { response, error, loading, refetch, fetchData };
};

export default useFetch;
