    "src/hooks/useProductListing.js": "import { useState, useEffect, useCallback } from 'react';
import useFetch from './useFetch'; // Assuming useFetch hook is correctly implemented

const useProductListing = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sortBy, setSortBy] = useState('');
  const [filters, setFilters] = useState({}); // e.g., { category: 'shoes', size: 'M', color: 'Blue' }

  const itemsPerPage = 12;

  // Helper to construct the API URL with current state
  const getApiUrl = useCallback(() => {
    const queryParams = new URLSearchParams({
      page: currentPage.toString(),
      limit: itemsPerPage.toString(),
      sort: sortBy || '', // Use sortBy state or default to empty
      ...(filters.category && { category: filters.category }),
      ...(filters.size && { size: filters.size }),
      ...(filters.color && { color: filters.color }),
      // Add other filters here as needed
    });
    return `/api/products?${queryParams.toString()}`;
  }, [currentPage, sortBy, filters, itemsPerPage]);

  // Fetch products using the useFetch hook
  const { response, error: fetchError, loading: fetchLoading, refetch } = useFetch(getApiUrl(), {
    immediate: true, // Fetch data when the hook mounts
    cacheDuration: 300, // Cache for 5 minutes
  });

  useEffect(() => {
    setLoading(fetchLoading);
    if (fetchError) {
      setError(fetchError);
      setProducts([]); // Clear products on error
    } else if (response) {
      setProducts(response.products || []);
      // Calculate total pages based on total items and items per page
      setTotalPages(Math.ceil((response.total || 0) / itemsPerPage));
    }
  }, [response, fetchError, fetchLoading]);

  // Function to handle page changes
  const handlePageChange = useCallback((page) => {
    setCurrentPage(page);
    // The getApiUrl will re-run due to dependency changes, triggering a fetch
  }, [getApiUrl]);

  // Function to handle sorting changes
  const handleSortChange = useCallback((selectedSort) => {
    setSortBy(selectedSort);
    setCurrentPage(1); // Reset to the first page when sorting changes
    // The getApiUrl will re-run, triggering a fetch
  }, [getApiUrl]);

  // Function to handle filter changes
  const handleFilterChange = useCallback((newFilters) => {
    setFilters(prevFilters => ({ ...prevFilters, ...newFilters }));
    setCurrentPage(1); // Reset to the first page when filters change
    // The getApiUrl will re-run, triggering a fetch
  }, [getApiUrl]);

  // Refetch function that might be useful for manual data refresh
  const refetchProducts = useCallback(() => {
    refetch(); // Use the refetch from useFetch
  }, [refetch]);

  return {
    products,
    loading,
    error,
    currentPage,
    totalPages,
    sortBy,
    filters,
    handlePageChange,
    handleSortChange,
    handleFilterChange,
    refetchProducts,
  };
};

export default useProductListing;
