/**
 * 🔥 Ultimate JSON Recovery Parser for AI Output
 * - Extracts the JSON object from the output
 * - Repairs missing commas between file entries
 * - Fixes trailing commas
 * - Fixes unescaped newlines
 * - Fixes broken string terminators
 * - Returns a valid JS object
 */

const raw = $json.output;

if (!raw || typeof raw !== "string") {
  return [{ json: { error: "No 'output' string found" } }];
}

// STEP 1 — Extract only the JSON object inside the fences
let cleaned = raw;

// remove fences
cleaned = cleaned.replace(/```json/gi, "").replace(/```/g, "").trim();

// extract the FIRST { ... } block
const match = cleaned.match(/\{[\s\S]*\}/);
if (!match) {
  return [{ json: { error: "No JSON-like object found" } }];
}

cleaned = match[0];

// STEP 2 — Basic cleanup
cleaned = cleaned
  .replace(/\\(?!["\\\/bfnrtu])/g, "\\\\")  // fix invalid backslashes
  .replace(/[\u0000-\u001F]/g, "")         // remove control chars
  .replace(/\r?\n/g, "\\n");               // convert newlines

// STEP 3 — Fix missing commas between file entries
// Example: "file1": "..."\n "file2": "..." → insert comma
cleaned = cleaned.replace(/\"\s*\n\s*\"/g, "\",\n  \"");

// STEP 4 — Fix trailing commas before }
cleaned = cleaned.replace(/,\s*}/g, "}");

// STEP 5 — Fix trailing commas before ]
cleaned = cleaned.replace(/,\s*]/g, "]");

// STEP 6 — Try parsing
let parsed = null;

