      "src/components/Navbar.jsx": "import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import Logo from './Logo';
import SearchBar from './SearchBar';
import ThemeToggle from './ThemeToggle';
import NotificationIcon from './NotificationIcon';
import ProfileMenu from './ProfileMenu';
import gsap from 'gsap';
import SidebarMobile from './SidebarMobile';

const Navbar = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 50) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);

    // GSAP animation for navbar shrink on scroll
    gsap.to('.navbar', {
      height: isScrolled ? '60px' : '80px',
      opacity: isScrolled ? 0.9 : 1,
      duration: 0.3,
      ease: 'power2.out',
    });

    // Close mobile menu when route changes
    setIsMobileMenuOpen(false);

    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, [isScrolled, location.pathname]); // Added location.pathname to re-run effect on route change

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <>
      <nav className="navbar bg-white dark:bg-gray-900 shadow-md sticky top-0 z-50 flex items-center justify-between px-4 py-4 transition-all duration-300 ease-in-out">
        <div className="flex items-center">
          <Link to="/">
            <Logo />
          </Link>
          <SearchBar />
        </div>
        <div className="flex items-center space-x-4">
          <ThemeToggle />
          <NotificationIcon />
          <ProfileMenu />
          <button onClick={toggleMobileMenu} className="md:hidden p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 focus:outline-none">
            <svg className="h-6 w-6 text-gray-600 dark:text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7"></path></svg>
          </button>
        </div>
      </nav>
      <SidebarMobile isOpen={isMobileMenuOpen} onClose={toggleMobileMenu} />
    </>
  );
};

export default Navbar;
