      "src/components/SearchBar.jsx": "import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import useFetch from '../hooks/useFetch';

const SearchBar = () => {
  const [query, setQuery] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const navigate = useNavigate();
  const location = useLocation();

  const { response: searchResponse, error: searchError, loading: searchLoading } = useFetch('/api/search/suggest', {
    params: { query: query },
    immediate: false, // Only fetch when query changes significantly
    cacheDuration: 60, // Cache suggestions for 1 minute
  });

  // Update suggestions when searchResponse changes
  useEffect(() => {
    if (searchResponse && searchResponse.suggestions) {
      setSuggestions(searchResponse.suggestions);
    } else {
      setSuggestions([]);
    }
  }, [searchResponse]);

  // Debounce query input to avoid excessive API calls
  useEffect(() => {
    const handler = setTimeout(() => {
      if (query.trim()) {
        // Trigger search suggestion fetch
        // We need to re-initialize useFetch or use a refetch mechanism here
        // For simplicity, a direct call is made here, but a dedicated hook management might be better
        fetch('/api/search/suggest?query=' + encodeURIComponent(query))
          .then(res => res.json())
          .then(data => setSuggestions(data.suggestions || []))
          .catch(err => console.error('Error fetching suggestions:', err));
      } else {
        setSuggestions([]);
      }
    }, 300);

    return () => {
      clearTimeout(handler);
    };
  }, [query]);

  const handleSearchChange = (e) => {
    setQuery(e.target.value);
  };

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    if (query.trim()) {
      navigate(`/products?search=${encodeURIComponent(query)}`);
      setSuggestions([]); // Clear suggestions on submit
    }
  };

  const handleSuggestionClick = (suggestion) => {
    navigate(`/products?search=${encodeURIComponent(suggestion)}`);
    setSuggestions([]); // Clear suggestions
    setQuery(''); // Clear input field
  };

  // Close suggestions when clicking outside the search bar area
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (document.getElementById('search-bar-container') && !document.getElementById('search-bar-container').contains(event.target)) {
        setSuggestions([]);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div id="search-bar-container" className="hidden md:flex items-center relative">
      <form onSubmit={handleSearchSubmit} className="flex items-center">
        <input
          type="text"
          placeholder="Search sportswear..."
          value={query}
          onChange={handleSearchChange}
          className="px-3 py-2 rounded-l-lg border border-gray-300 dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button
          type="submit"
          className="px-3 py-2 rounded-r-lg bg-blue-600 text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          Search
        </button>
      </form>
      {suggestions.length > 0 && (
        <div className="absolute top-full left-0 w-full bg-white dark:bg-gray-800 rounded-b-lg shadow-lg mt-1 border border-gray-200 dark:border-gray-700 z-10">
          {suggestions.map((suggestion, index) => (
            <div
              key={index}
              onClick={() => handleSuggestionClick(suggestion)}
              className="px-4 py-2 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700"
            >
              {suggestion}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SearchBar;
