const ItemDetailsPage = () => {
  const { itemId } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    gsap.fromTo(
      'main', 
      { opacity: 0, x: 50 },
      { opacity: 1, x: 0, duration: 0.5, ease: 'power2.out' }
    );

    const fetchProduct = async () => {
      setLoading(true);
      setError(null);
      try {
        await new Promise(resolve => setTimeout(resolve, 1000)); 
        const mockProduct = {
          id: itemId,
          name: "Example Sportswear Item",
          description: "This is a detailed description of the example sportswear item. It features advanced moisture-wicking fabric and ergonomic design for maximum comfort and performance. Engineered with Flywire technology for a secure fit and Zoom Air units for exceptional energy return. The durable rubber outsole provides excellent traction on various surfaces.",
