      "src/pages/ProductsPage.jsx": "import React, { useEffect, useState, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import ItemCard from '../components/ItemCard';
import FilterSidebar from '../components/FilterSidebar';
import Pagination from '../components/Pagination';
import SkeletonLoader from '../components/SkeletonLoader';
import SortingOptions from '../components/SortingOptions';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const ProductsPage = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sortBy, setSortBy] = useState('');
  const [filters, setFilters] = useState({});

  const itemsPerPage = 12;
  const location = useLocation();
  const navigate = useNavigate();

  const getQueryParams = (loc) => {
    const params = new URLSearchParams(loc.search);
    return {
      page: parseInt(params.get('page') || '1', 10),
      sort: params.get('sort') || '',
      category: params.get('category') || '',
      size: params.get('size') || '',
      color: params.get('color') || '',
      search: params.get('search') || '',
    };
  };

  const updateUrl = useCallback((newParams) => {
    const currentParams = getQueryParams(location);
    const mergedParams = { ...currentParams, ...newParams };
    const urlSearchParams = new URLSearchParams();

    Object.entries(mergedParams).forEach(([key, value]) => {
      if (value) {
        urlSearchParams.set(key, value);
      }
    });
    navigate(`?${urlSearchParams.toString()}`);
  }, [location, navigate]);

  useEffect(() => {
    gsap.fromTo(
      'main', 
      { opacity: 0, x: 50 },
      { opacity: 1, x: 0, duration: 0.5, ease: 'power2.out' }
    );
  }, []);

  const currentParams = getQueryParams(location);

  useEffect(() => {
    setCurrentPage(currentParams.page);
    setSortBy(currentParams.sort);
    setFilters({
      category: currentParams.category,
      size: currentParams.size,
      color: currentParams.color,
    });
  }, [location.search]);

  useEffect(() => {
    const fetchProducts = async () => {
      setLoading(true);
      setError(null);
      try {
        const queryParams = new URLSearchParams({
          page: currentPage.toString(),
          limit: itemsPerPage.toString(),
          sort: sortBy || '',
          ...(filters.category && { category: filters.category }),
          ...(filters.size && { size: filters.size }),
          ...(filters.color && { color: filters.color }),
          ...(currentParams.search && { search: currentParams.search }),
        });

        await new Promise(resolve => setTimeout(resolve, 1000)); 

        const mockResponse = {
          products: Array.from({ length: itemsPerPage }, (_, i) => {
            const productId = (currentPage - 1) * itemsPerPage + i + 1;
            return {
              id: `p${productId}`,
              name: `Product Name ${productId}`,
              price: (10 + productId * 1.5).toFixed(2),
              thumbnailUrl: `https://via.placeholder.com/300x200/f0f0f0/333333?text=Product+${productId}`,
              category: ['Shoes', 'Apparel', 'Accessories', 'Footwear', 'Sports Gear'][Math.floor(Math.random() * 5)],
            };
          }),
          total: 100, 
        };

        setProducts(mockResponse.products);
        setTotalPages(Math.ceil(mockResponse.total / itemsPerPage));
      } catch (err) {
        setError("Failed to load products.");
        console.error("Error fetching products:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, [currentPage, sortBy, filters, location.search]);

  useEffect(() => {
    if (!loading && products.length > 0) {
      const cardItems = gsap.utils.toArray('.product-card-item');
      cardItems.forEach((item, index) => {
        gsap.from(item, {
          opacity: 0,
          y: 30,
          scale: 0.98,
          duration: 0.6,
          ease: 'power3.out',
          scrollTrigger: {
            trigger: item,
            start: 'top 90%', 
            toggleActions: 'play none none none',
          },
          delay: index * 0.03 
        });
      });
    }
  }, [loading, products]);

  const handlePageChange = useCallback((page) => {
    updateUrl({ page: page.toString() });
  }, [updateUrl]);

  const handleSortChange = useCallback((selectedSort) => {
    setSortBy(selectedSort);
    updateUrl({ sort: selectedSort, page: '1' });
  }, [updateUrl]);

  const handleFilterChange = useCallback((newFilters) => {
    setFilters(prev => ({ ...prev, ...newFilters }));
    updateUrl({ ...newFilters, page: '1' });
  }, [updateUrl]);

  const renderSkeletonLoaders = () => (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {[...Array(itemsPerPage)].map((_, index) => (
        <SkeletonLoader key={index} type="item-card" />
      ))}
    </div>
  );

  if (loading) {
    return (
      <div className="flex flex-col md:flex-row gap-8 p-4 md:p-8">
        <div className="w-full md:w-1/4 lg:w-1/5">
          <SkeletonLoader type="filter-sidebar" />
        </div>
        <div className="flex-1">
          {renderSkeletonLoaders()}
          <SkeletonLoader type="pagination" className="mt-8" />
        </div>
      </div>
    );
  }

  if (error) {
    return <div className="text-red-500 text-center py-10">{error}</div>;
  }

  return (
    <div className="flex flex-col md:flex-row gap-8 p-4 md:p-8">
      <div className="w-full md:w-1/4 lg:w-1/5">
        <FilterSidebar onFilterChange={handleFilterChange} currentFilters={filters} />
      </div>
      <div className="flex-1">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold">Products</h1>
          <SortingOptions sortBy={sortBy} onSortChange={handleSortChange} />
        </div>
        {products.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
            {products.map(product => (
              <div key={product.id} className="product-card-item">
                <ItemCard
                  id={product.id}
                  name={product.name}
                  price={product.price}
                  thumbnailUrl={product.thumbnailUrl}
                  category={product.category}
                />
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-10 text-gray-500 dark:text-gray-400">
            No products found matching your criteria.
          </div>
        )}
        {totalPages > 1 && (
          <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={handlePageChange} />
        )}
      </div>
    </div>
  );
};

export default ProductsPage;
