      "src/components/FilterSidebar.jsx": "import React, { useState, useEffect } from 'react';

const FilterSidebar = ({ onFilterChange, currentFilters }) => {
  const categories = ['All', 'Running Shoes', 'T-Shirts', 'Shorts', 'Jackets', 'Accessories'];
  const sizes = ['XS', 'S', 'M', 'L', 'XL', 'XXL'];
  const colors = ['Black', 'White', 'Blue', 'Red', 'Green', 'Grey'];

  const [selectedCategory, setSelectedCategory] = useState(currentFilters?.category || 'All');
  const [selectedSize, setSelectedSize] = useState(currentFilters?.size || '');
  const [selectedColor, setSelectedColor] = useState(currentFilters?.color || '');

  useEffect(() => {
    setSelectedCategory(currentFilters?.category || 'All');
    setSelectedSize(currentFilters?.size || '');
    setSelectedColor(currentFilters?.color || '');
  }, [currentFilters]);

  const handleCategoryChange = (e) => {
    const newCategory = e.target.value;
    setSelectedCategory(newCategory);
    onFilterChange({ category: newCategory === 'All' ? '' : newCategory });
  };

  const handleSizeChange = (e) => {
    const newSize = e.target.value;
    setSelectedSize(newSize);
    onFilterChange({ size: newSize });
  };

  const handleColorChange = (e) => {
    const newColor = e.target.value;
    setSelectedColor(newColor);
    onFilterChange({ color: newColor });
  };

  const resetFilters = () => {
    setSelectedCategory('All');
    setSelectedSize('');
    setSelectedColor('');
    onFilterChange({ category: '', size: '', color: '' });
  };

  return (
    <div className="sticky top-24 bg-white dark:bg-gray-800 p-6 rounded-lg shadow-lg">
      <h3 className="text-xl font-bold mb-4 text-gray-900 dark:text-white">Filters</h3>

      <div className="mb-6">
        <label htmlFor="category" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Category</label>
        <select 
          id="category"
          value={selectedCategory}
          onChange={handleCategoryChange}
          className="w-full px-3 py-2 border border-gray-300 dark:bg-gray-700 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          {categories.map(cat => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      <div className="mb-6">
        <label htmlFor="size" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Size</label>
        <select 
          id="size"
          value={selectedSize}
          onChange={handleSizeChange}
          className="w-full px-3 py-2 border border-gray-300 dark:bg-gray-700 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="">All Sizes</option>
          {sizes.map(size => (
            <option key={size} value={size}>{size}</option>
          ))}
        </select>
      </div>

      <div className="mb-6">
        <label htmlFor="color" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Color</label>
        <select 
          id="color"
          value={selectedColor}
          onChange={handleColorChange}
          className="w-full px-3 py-2 border border-gray-300 dark:bg-gray-700 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="">All Colors</option>
          {colors.map(color => (
            <option key={color} value={color}>{color}</option>
          ))}
        </select>
      </div>

      <button 
        onClick={resetFilters}
        className="w-full py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 font-medium rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 focus:outline-none focus:ring-2 focus:ring-gray-400"
      >
        Reset Filters
      </button>
    </div>
  );
};

export default FilterSidebar;
