      "src/components/Carousel.jsx": "import React, { useState, Children, useEffect } from 'react';
import { FaChevronLeft, FaChevronRight } from 'react-icons/fa';

const Carousel = ({ children }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const totalItems = Children.count(children);
  const [itemsToShow, setItemsToShow] = useState(3);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setItemsToShow(1);
      } else if (window.innerWidth < 1024) {
        setItemsToShow(2);
      } else {
        setItemsToShow(3);
      }
    };

    window.addEventListener('resize', handleResize);
    handleResize();

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const goToPrevious = () => {
    const newIndex = currentIndex === 0 ? totalItems - 1 : currentIndex - 1;
    setCurrentIndex(newIndex);
  };

  const goToNext = () => {
    const newIndex = currentIndex === totalItems - 1 ? 0 : currentIndex + 1;
    setCurrentIndex(newIndex);
  };

  const slideWidth = `${100 / itemsToShow}%`;

  const carouselStyle = {
    transform: `translateX(-${currentIndex * (100 / itemsToShow)}%)`,
    transition: 'transform 0.5s ease-in-out',
    display: 'flex',
    width: `${totalItems * (100 / itemsToShow)}%` 
  };

  return (
    <div className="relative w-full overflow-hidden">
      <div className="flex items-center justify-between absolute top-1/2 -translate-y-1/2 z-10 w-full px-4">
        <button onClick={goToPrevious} className="p-3 rounded-full bg-gray-800 bg-opacity-50 text-white hover:bg-opacity-75 focus:outline-none">
          <FaChevronLeft />
        </button>
        <button onClick={goToNext} className="p-3 rounded-full bg-gray-800 bg-opacity-50 text-white hover:bg-opacity-75 focus:outline-none">
          <FaChevronRight />
        </button>
      </div>
      <div className="overflow-hidden">
        <div style={carouselStyle}>
          {Children.map(children, (child, index) => (
            <div key={index} className="flex-shrink-0" style={{ flexBasis: slideWidth }}> 
              {child}
            </div>
          ))}
        </div>
      </div>

      <div className="flex justify-center mt-4">
        {Array.from({ length: totalItems }, (_, i) => (
          <button 
            key={i}
            onClick={() => setCurrentIndex(i)}
            className={`w-3 h-3 rounded-full mx-1 focus:outline-none ${currentIndex === i ? 'bg-blue-600' : 'bg-gray-400 dark:bg-gray-600'}`}
          />
        ))}
      </div>
    </div>
  );
};

export default Carousel;
