      "src/hooks/useFetch.jsx": "import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const useFetch = (url, options = {}) => {
  const { method = 'get', params, data, headers, immediate = true, cacheDuration = 0, ...axiosOptions } = options;
  const [response, setResponse] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(immediate);
  const [abortController, setAbortController] = useState(null);
  const [cache, setCache] = useState({});

  const fetchData = useCallback(async (fetchUrl = url) => {
    if (!fetchUrl) {
      setLoading(false);
      return;
    }

    if (cacheDuration > 0 && cache[fetchUrl] && cache[fetchUrl].timestamp > Date.now() - cacheDuration * 1000) {
      setResponse(cache[fetchUrl].data);
      setLoading(false);
      return;
    }

    if (abortController) {
      abortController.abort();
    }

    const controller = new AbortController();
    setAbortController(controller);

    setLoading(true);
    setError(null);

    try {
      const config = {
        method,
        url: fetchUrl,
        params: params,
        data: data,
        headers: { ...headers },
        signal: controller.signal,
        ...axiosOptions,
      };

      const result = await axios(config);
      const fetchedData = result.data;

      setResponse(fetchedData);

      if (cacheDuration > 0) {
        setCache({
          ...cache,
          [fetchUrl]: { data: fetchedData, timestamp: Date.now() },
        });
      }

    } catch (err) {
      if (err.name === 'AbortError') {
        console.log('Fetch aborted');
      } else {
        setError(err);
      }
    } finally {
      setLoading(false);
      setAbortController(null);
    }
  }, [url, method, params, data, headers, cacheDuration, cache, abortController]);

  useEffect(() => {
    if (immediate) {
      fetchData();
    }
    return () => {
      if (abortController) {
        abortController.abort();
      }
    };
  }, [fetchData, immediate]);

  const refetch = useCallback(() => {
    fetchData(url);
  }, [fetchData, url]);

  return { response, error, loading, refetch, fetchData };
};

export default useFetch;
