      "src/hooks/useHomeData.jsx": "import { useState, useEffect } from 'react';
import useFetch from './useFetch';

const useHomeData = () => {
  const [featuredProducts, setFeaturedProducts] = useState([]);
  const [likedItems, setLikedItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const { response: featuredResponse, error: featuredError, fetchData: fetchFeatured } = useFetch('/api/products', {
    params: { featured: true, limit: 5 },
    cacheDuration: 300,
  });

  const { response: likedResponse, error: likedError, fetchData: fetchLiked } = useFetch('/api/user/liked', {
    immediate: true,
    cacheDuration: 60,
  });

  useEffect(() => {
    if (featuredResponse && likedResponse) {
      setFeaturedProducts(featuredResponse.products || []);
      setLikedItems(likedResponse.likedItems || []);
      setLoading(false);
    } else if (featuredError || likedError) {
      setError(featuredError || likedError || new Error('Failed to load home data'));
      setLoading(false);
    }

    if ((!featuredResponse && !featuredError && featuredResponse !== null) || (!likedResponse && !likedError && likedResponse !== null)) {
      setLoading(true);
    } else {
      setLoading(false);
    }

  }, [featuredResponse, featuredError, likedResponse, likedError]);

  const refetch = () => {
    fetchFeatured();
    fetchLiked();
  };

  return {
    featuredProducts,
    likedItems,
    loading,
    error,
    refetch,
  };
};

export default useHomeData;
