      "src/hooks/useProductListing.jsx": "import { useState, useEffect, useCallback } from 'react';
import useFetch from './useFetch';

const useProductListing = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sortBy, setSortBy] = useState('');
  const [filters, setFilters] = useState({});

  const itemsPerPage = 12;

  const getApiUrl = useCallback(() => {
    const queryParams = new URLSearchParams({
      page: currentPage.toString(),
      limit: itemsPerPage.toString(),
      sort: sortBy || '',
      ...(filters.category && { category: filters.category }),
      ...(filters.size && { size: filters.size }),
      ...(filters.color && { color: filters.color }),
    });
    return `/api/products?${queryParams.toString()}`;
  }, [currentPage, sortBy, filters, itemsPerPage]);

  const { response, error: fetchError, loading: fetchLoading, fetchData: refetchFetch } = useFetch(getApiUrl(), {
    immediate: true,
    cacheDuration: 300,
  });

  useEffect(() => {
    setLoading(fetchLoading);
    if (fetchError) {
      setError(fetchError);
      setProducts([]);
    } else if (response) {
      setProducts(response.products || []);
      setTotalPages(Math.ceil((response.total || 0) / itemsPerPage));
    }
  }, [response, fetchError, fetchLoading]);

  const handlePageChange = useCallback((page) => {
    setCurrentPage(page);
  }, []);

  const handleSortChange = useCallback((selectedSort) => {
    setSortBy(selectedSort);
    setCurrentPage(1);
  }, []);

  const handleFilterChange = useCallback((newFilters) => {
    setFilters(prevFilters => ({ ...prevFilters, ...newFilters }));
    setCurrentPage(1);
  }, []);

  const refetchProducts = useCallback(() => {
    refetchFetch();
  }, [refetchFetch]);

  return {
    products,
    loading,
    error,
    currentPage,
    totalPages,
    sortBy,
    filters,
    handlePageChange,
    handleSortChange,
    handleFilterChange,
    refetchProducts,
  };
};

export default useProductListing;
