/**
 * 🔥 Ultimate JSON Recovery Parser for AI Output + JSON File Stringifier
 * - Extracts JSON object from AI output
 * - Repairs missing commas, trailing commas, escape issues
 * - Detects JSON-based files (ex: package.json) and converts to a JSON string
 */

const raw = $json.output;

if (!raw || typeof raw !== "string") {
  return [{ json: { error: "No 'output' string found" } }];
}

// STEP 1 — Extract only the JSON object inside the fences
let cleaned = raw;

// remove ```json fences
cleaned = cleaned.replace(/```json/gi, "").replace(/```/g, "").trim();

// extract first { ... } block
const match = cleaned.match(/\{[\s\S]*\}/);
if (!match) {
  return [{ json: { error: "No JSON-like object found" } }];
}
cleaned = match[0];

// STEP 2 — Basic cleanup
cleaned = cleaned
  .replace(/\\(?!["\\\/bfnrtu])/g, "\\\\")     // fix invalid backslashes
  .replace(/[\u0000-\u001F]/g, "")            // remove control chars
  .replace(/\r?\n/g, "\\n");                  // convert newlines

// STEP 3 — Fix missing commas between file entries
cleaned = cleaned.replace(/\"\s*\n\s*\"/g, "\",\n  \"");

// STEP 4 — Fix trailing commas
cleaned = cleaned.replace(/,\s*}/g, "}").replace(/,\s*]/g, "]");

// STEP 5 — Try parsing
let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [
    {
      json: {
        error: "JSON parse failed after repairs",
        message: err.message,
        cleaned_preview: cleaned.slice(0, 800)
      }
    }
  ];
}

// ----------------------------------------------------------
// ⭐ STEP 6 — Convert JSON-file objects into stringified JSON
// ----------------------------------------------------------

const jsonFileRegex = /\.json$/i;

for (const key of Object.keys(parsed)) {
  const value = parsed[key];

  if (jsonFileRegex.test(key)) {

    // 💡 If already a string → LEAVE IT AS IS
    if (typeof value === "string") {
      continue;
    }

    // 💡 If it's an object → convert to pretty JSON string
    if (typeof value === "object" && !Array.isArray(value)) {
      parsed[key] = JSON.stringify(value, null, 2);
    }
  }
}

// Return final result
return [{ json: { cleaned_folder_json: parsed } }];
